create table emk_app.emk_claims_jn (
    jn_id                  number generated always as identity not null enable,
    jn_operation           char(1 char) not null enable,
    jn_at                  timestamp(6) with time zone default on null systimestamp not null enable,
    jn_by                  varchar2(255 char) default on null coalesce(
        sys_context('APEX$SESSION', 'APP_USER'),
        sys_context('USERENV', 'PROXY_USER'),
        sys_context('USERENV', 'SESSION_USER')
    ) not null enable,
    jn_on                  date generated always as ( cast(sys_extract_utc(jn_at) as date) ) virtual,
    claim_id               number,
    claim_no               varchar2(15 char),
    shipment_id            number,
    claim_type             varchar2(20 char),
    damage_apparent_yn     char(1 char),
    status                 varchar2(20 char),
    handler                varchar2(255 char),
    registration_date      date,
    joint_check_date       date,
    reservation_date       date,
    written_claim_date     date,
    carrier_rejection_date date,
    weight_short_kg        number(12, 3),
    claimed_amount         number(14, 2),
    settled_amount         number(14, 2),
    recovered_amount       number(14, 2),
    currency_code          char(3 char),
    description            varchar2(1000 char),
    created_at             timestamp(6) with time zone,
    created_by             varchar2(255 char),
    updated_at             timestamp(6) with time zone,
    updated_by             varchar2(255 char),
    deleted_yn             char(1 char),
    deleted_by             varchar2(255 char),
    deleted_at             timestamp(6) with time zone
)
    partition by range (
        jn_on
    ) interval ( numtoyminterval(1, 'MONTH') ) ( partition p_initial
        values less than ( to_date(' 2026-01-01 00:00:00', 'SYYYY-MM-DD HH24:MI:SS', 'NLS_CALENDAR=GREGORIAN') )
    );

alter table emk_app.emk_claims_jn
    add constraint emk_claims_jn_op_ck
        check ( jn_operation in ( 'U', 'D' ) ) enable;

alter table emk_app.emk_claims_jn
    add constraint emk_claims_jn_pk primary key ( jn_id )
        using index enable;


